window.__PAGE_TRANSLATIONS__ = {"info/sobre.html":{"en":{"title":"About | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><p class=\"article-eyebrow\">The laboratory</p><h1 data-i18n=\"pages.about.title\">About Inspetor BudGanja</h1><p class=\"page-intro\" data-i18n=\"pages.about.subtitle\">A digital space dedicated to Brazil's medicinal plants: a curated catalog, UNIFESP continuing education, documented legacy, verifiable inspections, a video hub, and practical tools for responsible study and cultivation.</p></header><section class=\"sobre-story\" aria-labelledby=\"sobre-story-title\"><h2 id=\"sobre-story-title\" class=\"visually-hidden\">Who we are</h2><p>Inspetor BudGanja was created to bring botanical knowledge, continuing education, and laboratory practice together in one place. We document species used in folk medicine; follow the <a href=\"/biblioteca/unifesp/\">UNIFESP course</a> on medicinal cannabis and the <strong>MovReCam</strong> and <strong>CANABinALL</strong> channels; record the <strong>credit due</strong> to founding figures such as <a href=\"/posts/post-inspecao-padre-ticao.html\">Father Ticão</a> and <a href=\"/posts/post-inspecao-elisaldo-carlini.html\">Prof. Elisaldo Carlini</a>; and gather lectures and outreach in the <a href=\"/videos/\">video hub</a> — with the research journal, community, BudGanja Radio, and the @InspetorBudGanja channel supporting the laboratory.</p></section><section class=\"info-panel sobre-author\" aria-labelledby=\"sobre-author-title\"><h2 id=\"sobre-author-title\">Who is behind it</h2><p class=\"info-panel-text\"><strong>Tiago Queiroz Loureiro</strong> — computer scientist focused on controlled-environment agriculture (CEA), automation, and agricultural IoT. He combines computational precision and botany to turn cultivation protocols into practical tools — Inspetor BudGanja is the public laboratory for this work.</p><p class=\"section-cta-inline\"><a href=\"https://www.linkedin.com/in/tiago-queiroz-loureiro/\" class=\"botao botao-outline btn-inline\" target=\"_blank\" rel=\"noopener noreferrer\">LinkedIn</a></p></section><div class=\"section-grid sobre-grid\"><section class=\"info-panel\"><h3>Mission</h3><ul class=\"info-list\"><li>Democratize access to clear information about medicinal plants.</li><li>Connect UNIFESP continuing education to the catalog and practical laboratory.</li><li>Give public credit to those who founded and sustained the ecosystem — legacy, science, and the periphery.</li><li>Review channels, courses, articles, and equipment using a verifiable method.</li><li>Record methods and results with rigor that is useful day to day.</li></ul></section><section class=\"info-panel\"><h3>How we work</h3><ul class=\"info-list\"><li>Lightweight content, readable on mobile and installable as a PWA.</li><li>Editorial profiles and hubs with sources and limitations in plain sight.</li><li>Independent reviews — no commercial or institutional affiliation with audited subjects.</li><li>In-site video hub (Inspector, MovReCam, CANABinALL) for studying without leaving the laboratory.</li><li>Browser-based tools — immediate response and offline use after installation.</li></ul></section></div><section class=\"sobre-paths\" aria-labelledby=\"sobre-paths-title\"><h2 id=\"sobre-paths-title\">What you will find</h2><ul class=\"sobre-paths-list\"><li><a href=\"/plantas/\">Plants</a> — catalog of Brazilian herbal medicine profiles</li><li><a href=\"/biblioteca/unifesp/\">UNIFESP Course</a> — hub for the 14th continuing-education course</li><li><a href=\"/biblioteca/inspecoes/\">Inspections</a> — legacy (Ticão, Carlini), channels, courses, articles, and equipment</li><li><a href=\"/videos/\">Videos</a> — in-site player with MovReCam, CANABinALL, and @InspetorBudGanja</li><li><a href=\"/calculadoras/\">Tools</a> — VPD, DLI, EC, light meter, and soil</li><li><a href=\"/cultivo/\">Research journal</a> — stages, notes, and plans</li><li><a href=\"/comunidade/\">Community</a> — feed, photos, and plant identification</li><li><a href=\"/equipamentos/\">Equipment</a> — cloning-machine and hydro-cloner manuals</li><li><a href=\"/radio/\">BudGanja Radio</a> — the laboratory playlist</li></ul></section><section class=\"info-panel sobre-limits\"><h3>Limitations</h3><ul class=\"info-list\"><li>Camera measurements and calculators are estimates — they do not replace laboratory instruments.</li><li>Results depend on the device, calibration, and environment.</li><li>Plant profiles and inspections are educational — they do not replace medical, pharmaceutical, or legal advice.</li><li>Content adapts to your legal and technical reality; always confirm official sources (e.g., SIEX/UNIFESP).</li></ul></section><section class=\"sobre-cta info-panel\" aria-labelledby=\"sobre-cta-title\"><h3 id=\"sobre-cta-title\">Channel, privacy, and contact</h3><p class=\"info-panel-text\">Videos and tutorials on YouTube; episodes on Spotify. Data transparency is detailed in the privacy policy.</p><p class=\"section-cta-inline\"><a href=\"/info/apresentacao-unifesp.html\" class=\"botao btn-inline\">UNIFESP Presentation</a><a href=\"/videos/\" class=\"botao botao-outline btn-inline\">Videos</a><a href=\"https://open.spotify.com/show/033yuLDWnN84xOcfHyJ1FZ\" class=\"botao botao-outline btn-inline\" target=\"_blank\" rel=\"noopener noreferrer\">Spotify</a><a href=\"/info/privacidade.html\" class=\"botao botao-outline btn-inline\">Privacy</a><a href=\"/info/contato.html\" class=\"botao botao-outline btn-inline\">Contact</a></p></section>"},"es":{"title":"Acerca de | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><p class=\"article-eyebrow\">El laboratorio</p><h1 data-i18n=\"pages.about.title\">Acerca de Inspetor BudGanja</h1><p class=\"page-intro\" data-i18n=\"pages.about.subtitle\">Espacio digital dedicado a las plantas medicinales de Brasil: catálogo curado, extensión académica UNIFESP, legado documentado, inspecciones con método verificable, hub de videos y herramientas prácticas para el estudio y cultivo responsables.</p></header><section class=\"sobre-story\" aria-labelledby=\"sobre-story-title\"><h2 id=\"sobre-story-title\" class=\"visually-hidden\">Quiénes somos</h2><p>Inspetor BudGanja nació para acercar el conocimiento botánico, la formación de extensión y la práctica de laboratorio en un solo lugar. Documentamos especies usadas en la medicina popular; seguimos el <a href=\"/biblioteca/unifesp/\">curso UNIFESP</a> de cannabis medicinal y los canales <strong>MovReCam</strong> y <strong>CANABinALL</strong>; registramos el <strong>mérito debido</strong> a figuras de origen como el <a href=\"/posts/post-inspecao-padre-ticao.html\">Padre Ticão</a> y el <a href=\"/posts/post-inspecao-elisaldo-carlini.html\">Prof. Elisaldo Carlini</a>; y reunimos clases y divulgación en el <a href=\"/videos/\">hub de videos</a> — con el diario de investigaciones, la comunidad, BudGanja Radio y el canal @InspetorBudGanja como apoyos del laboratorio.</p></section><section class=\"info-panel sobre-author\" aria-labelledby=\"sobre-author-title\"><h2 id=\"sobre-author-title\">Quién está detrás</h2><p class=\"info-panel-text\"><strong>Tiago Queiroz Loureiro</strong> — científico de la computación, enfocado en ambientes controlados (CEA), automatización e IoT agrícola. Une precisión computacional y botánica para transformar protocolos de cultivo en herramientas prácticas — Inspetor BudGanja es el laboratorio público de este trabajo.</p><p class=\"section-cta-inline\"><a href=\"https://www.linkedin.com/in/tiago-queiroz-loureiro/\" class=\"botao botao-outline btn-inline\" target=\"_blank\" rel=\"noopener noreferrer\">LinkedIn</a></p></section><div class=\"section-grid sobre-grid\"><section class=\"info-panel\"><h3>Misión</h3><ul class=\"info-list\"><li>Democratizar el acceso a información clara sobre plantas medicinales.</li><li>Conectar la extensión académica (UNIFESP) con el catálogo y el laboratorio práctico.</li><li>Dar crédito público a quienes fundaron y sostuvieron el ecosistema — legado, ciencia y periferia.</li><li>Inspeccionar canales, cursos, artículos y equipos con un método verificable.</li><li>Registrar métodos y resultados con rigor útil en el día a día.</li></ul></section><section class=\"info-panel\"><h3>Cómo trabajamos</h3><ul class=\"info-list\"><li>Contenido ligero, legible en el celular e instalable como PWA.</li><li>Fichas y hubs editoriales con fuentes y límites a la vista.</li><li>Inspecciones independientes — sin afiliación comercial ni institucional con los objetos auditados.</li><li>Hub de videos in-site (Inspector, MovReCam, CANABinALL) para estudiar sin salir del laboratorio.</li><li>Herramientas en el navegador — respuesta inmediata y uso sin conexión después de instalar.</li></ul></section></div><section class=\"sobre-paths\" aria-labelledby=\"sobre-paths-title\"><h2 id=\"sobre-paths-title\">Qué encontrarás</h2><ul class=\"sobre-paths-list\"><li><a href=\"/plantas/\">Plantas</a> — catálogo de fichas fitoterapéuticas de Brasil</li><li><a href=\"/biblioteca/unifesp/\">Curso UNIFESP</a> — hub del XIV curso de extensión</li><li><a href=\"/biblioteca/inspecoes/\">Inspecciones</a> — legado (Ticão, Carlini), canales, cursos, artículos y equipos</li><li><a href=\"/videos/\">Videos</a> — reproductor in-site con MovReCam, CANABinALL y @InspetorBudGanja</li><li><a href=\"/calculadoras/\">Herramientas</a> — VPD, DLI, EC, luxómetro y suelo</li><li><a href=\"/cultivo/\">Diario de investigaciones</a> — fases, notas y planes</li><li><a href=\"/comunidade/\">Comunidad</a> — feed, fotos e identificación de plantas</li><li><a href=\"/equipamentos/\">Equipos</a> — manuales de clonadora e hidroclonadora</li><li><a href=\"/radio/\">BudGanja Radio</a> — lista de reproducción del laboratorio</li></ul></section><section class=\"info-panel sobre-limits\"><h3>Límites</h3><ul class=\"info-list\"><li>Las mediciones por cámara y las calculadoras son estimaciones — no sustituyen instrumentos de laboratorio.</li><li>Los resultados dependen del dispositivo, la calibración y el ambiente.</li><li>Las fichas de plantas e inspecciones son educativas — no sustituyen orientación médica, farmacéutica ni jurídica.</li><li>El contenido se adapta a tu realidad legal y técnica; confirma siempre las fuentes oficiales (p. ej., SIEX/UNIFESP).</li></ul></section><section class=\"sobre-cta info-panel\" aria-labelledby=\"sobre-cta-title\"><h3 id=\"sobre-cta-title\">Canal, privacidad y contacto</h3><p class=\"info-panel-text\">Videos y tutoriales en YouTube; episodios en Spotify. Transparencia de datos en la política de privacidad.</p><p class=\"section-cta-inline\"><a href=\"/info/apresentacao-unifesp.html\" class=\"botao btn-inline\">Presentación UNIFESP</a><a href=\"/videos/\" class=\"botao botao-outline btn-inline\">Videos</a><a href=\"https://open.spotify.com/show/033yuLDWnN84xOcfHyJ1FZ\" class=\"botao botao-outline btn-inline\" target=\"_blank\" rel=\"noopener noreferrer\">Spotify</a><a href=\"/info/privacidad.html\" class=\"botao botao-outline btn-inline\">Privacidad</a><a href=\"/info/contato.html\" class=\"botao botao-outline btn-inline\">Contacto</a></p></section>"}},"info/contato.html":{"en":{"title":"Contact | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><p class=\"article-eyebrow\">Information</p><h1 data-i18n=\"pages.contact.title\">Contact Inspetor BudGanja</h1><p class=\"page-intro\" data-i18n=\"pages.contact.subtitle\">Questions about research, reviews, equipment, or giveaways? Choose the most convenient channel.</p></header><div class=\"post-content\"><div class=\"contact-grid\"><div class=\"highlight highlight-box contact-card\"><h3>📧 Email</h3><p>Reply within 48 business hours.</p><p><a class=\"contact-email\" href=\"mailto:tql.tql@gmail.com\">tql.tql@gmail.com</a></p></div><div class=\"highlight highlight-box contact-card\"><h3>📺 Videos</h3><p>Tutorials, reviews, and live giveaways.</p><p><a class=\"contact-email\" href=\"/videos/\">@InspetorBudGanja</a></p></div><div class=\"highlight highlight-box contact-card\"><h3>🎁 Giveaways</h3><p>Registration and rules for the active giveaway.</p><p><a class=\"contact-email\" href=\"/sorteios/\">Enter the giveaway →</a></p></div></div><section class=\"contact-faq\"><h2>Frequently asked questions</h2><details><summary>How can I suggest a research or review topic?</summary><p>Send an email with as much technical detail as possible (equipment, environment, objective). We evaluate suggestions for the Cultivation Library.</p></details><details><summary>Can I use the tools offline?</summary><p>Yes. Install the site as an app (PWA) or access it while connected — the tools run in your browser.</p></details><details><summary>How do giveaways work?</summary><p>Each giveaway has its own rules on the <a href=\"/sorteios/\">Giveaways</a> page. Data is used only for contact, according to the <a href=\"/info/privacidade.html\">privacy policy</a>.</p></details></section><section class=\"newsletter-cta highlight highlight-box\" id=\"sorteio-alerts-section\"><h2>Receive giveaway alerts</h2><p id=\"sorteio-alerts-intro\">Sign in with your Google account and subscribe to receive alerts when we open a new giveaway.</p><p id=\"sorteio-alerts-status\" class=\"sorteios-message\" role=\"status\" hidden></p><div class=\"newsletter-cta-actions\"><button type=\"button\" id=\"sorteio-alerts-btn\" class=\"botao botao-home\">I want to receive alerts</button><button type=\"button\" id=\"sorteio-alerts-unsub-btn\" class=\"botao botao-outline botao-sm\" hidden>Cancel alerts</button></div></section><p class=\"section-subtitle\" style=\"margin-top: 32px;\">Location: Experimental Laboratory (digital content)</p></div>"},"es":{"title":"Contacto | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><p class=\"article-eyebrow\">Información</p><h1 data-i18n=\"pages.contact.title\">Contacto con Inspetor BudGanja</h1><p class=\"page-intro\" data-i18n=\"pages.contact.subtitle\">¿Preguntas sobre investigaciones, inspecciones, equipos o sorteos? Elige el canal más conveniente.</p></header><div class=\"post-content\"><div class=\"contact-grid\"><div class=\"highlight highlight-box contact-card\"><h3>📧 Correo electrónico</h3><p>Respuesta en hasta 48 h hábiles.</p><p><a class=\"contact-email\" href=\"mailto:tql.tql@gmail.com\">tql.tql@gmail.com</a></p></div><div class=\"highlight highlight-box contact-card\"><h3>📺 Videos</h3><p>Tutoriales, inspecciones y sorteos en vivo.</p><p><a class=\"contact-email\" href=\"/videos/\">@InspetorBudGanja</a></p></div><div class=\"highlight highlight-box contact-card\"><h3>🎁 Sorteos</h3><p>Inscripciones y reglamento del sorteo activo.</p><p><a class=\"contact-email\" href=\"/sorteios/\">Participar en el sorteo →</a></p></div></div><section class=\"contact-faq\"><h2>Preguntas frecuentes</h2><details><summary>¿Cómo sugiero un tema de investigación o inspección?</summary><p>Envía un correo con el máximo de detalles técnicos (equipo, ambiente, objetivo). Evaluamos sugerencias para la Biblioteca de Cultivo.</p></details><details><summary>¿Puedo usar las herramientas sin conexión?</summary><p>Sí. Instala el sitio como app (PWA) o accede con conexión — las herramientas funcionan en tu navegador.</p></details><details><summary>¿Cómo funcionan los sorteos?</summary><p>Cada sorteo tiene reglas propias en la página <a href=\"/sorteios/\">Sorteos</a>. Los datos se usan solo para contacto, de acuerdo con la <a href=\"/info/privacidade.html\">política de privacidad</a>.</p></details></section><section class=\"newsletter-cta highlight highlight-box\" id=\"sorteio-alerts-section\"><h2>Recibir avisos de sorteos</h2><p id=\"sorteio-alerts-intro\">Ingresa con tu cuenta Google y suscríbete para recibir avisos cuando abramos un nuevo sorteo.</p><p id=\"sorteio-alerts-status\" class=\"sorteios-message\" role=\"status\" hidden></p><div class=\"newsletter-cta-actions\"><button type=\"button\" id=\"sorteio-alerts-btn\" class=\"botao botao-home\">Quiero recibir avisos</button><button type=\"button\" id=\"sorteio-alerts-unsub-btn\" class=\"botao botao-outline botao-sm\" hidden>Cancelar avisos</button></div></section><p class=\"section-subtitle\" style=\"margin-top: 32px;\">Ubicación: Laboratorio Experimental (contenido digital)</p></div>"}},"info/privacidade.html":{"en":{"title":"Privacy | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><p class=\"article-eyebrow\">Information</p><h1 data-i18n=\"pages.privacy.title\">Privacy Policy</h1><p class=\"page-intro\" data-i18n=\"pages.privacy.subtitle\">Inspetor BudGanja handles personal data transparently and only for clear purposes. This document describes what we collect, why, and what your rights are.</p></header><div class=\"post-content\"><section class=\"info-panel highlight-card\"><h2>Quick summary</h2><ul class=\"info-list\"><li>We do not sell personal data.</li><li>Giveaways use data only for contact and registration validation.</li><li>You can request deletion by writing to <a href=\"mailto:tql.tql@gmail.com\">tql.tql@gmail.com</a>.</li></ul></section><h2>1. Who we are</h2><p>The <strong>Inspetor BudGanja</strong> website is a digital laboratory of educational content about plant cultivation. Official contact: <a href=\"mailto:tql.tql@gmail.com\">tql.tql@gmail.com</a>.</p><h2>2. Data collected</h2><h3>Giveaways (internal form)</h3><p>When you enter a giveaway through the site form, we may collect:</p><ul><li>Full name, CPF, email, and phone number</li><li>City, state, and Instagram (optional)</li><li>Date/time of registration and selected prize, if applicable</li></ul><h3>Giveaways (Google Forms)</h3><p>If the giveaway uses an external Google form, data is processed by Google under the <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener noreferrer\">Google Privacy Policy</a>. Also consult the privacy settings defined by the form administrator.</p><h3>Website navigation</h3><p>The server may record technical logs (IP, date, page accessed) for security and diagnostics. We do not use advertising-tracking cookies.</p><h2>3. Purpose of processing</h2><ul><li>Validate giveaway registrations (one per CPF/email)</li><li>Contact winners and answer questions</li><li>Keep the website secure and functional</li></ul><h2>4. Legal basis (LGPD)</h2><p>Processing is based on <strong>consent</strong> (acceptance in the giveaway form) and <strong>legitimate interest</strong> for the technical operation of the site, always respecting your rights.</p><h2>5. Retention</h2><p>Giveaway data is kept for the period needed to run the giveaway, contact the winner, and meet legal obligations. After that period, it may be anonymized or deleted.</p><h2>6. Your rights</h2><p>You may request:</p><ul><li>Confirmation and access to data</li><li>Correction of incomplete or outdated data</li><li>Deletion of data processed with consent</li><li>Withdrawal of consent</li></ul><p>Send requests to <a href=\"mailto:tql.tql@gmail.com\">tql.tql@gmail.com</a> with the subject <em>Privacy — LGPD</em>.</p><h2>7. Security</h2><p>We apply reasonable technical measures (HTTPS in production, restricted access to the admin panel, environment passwords). No system is 100% invulnerable; we recommend not reusing important passwords in public forms.</p><h2>8. Changes</h2><p>This policy may be updated. The date of the last review appears in the site footer.</p><p class=\"privacy-updated\"><em>Last updated: June 26, 2026.</em></p><p class=\"section-cta-inline\"><a href=\"/sorteios/\" class=\"botao btn-inline\">View giveaways</a><a href=\"/info/contato.html\" class=\"botao admin-secondary btn-inline\">Contact us</a></p></div>"},"es":{"title":"Privacidad | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><p class=\"article-eyebrow\">Información</p><h1 data-i18n=\"pages.privacy.title\">Política de Privacidad</h1><p class=\"page-intro\" data-i18n=\"pages.privacy.subtitle\">Inspetor BudGanja trata los datos personales con transparencia y solo para finalidades claras. Este documento describe qué recopilamos, por qué y cuáles son tus derechos.</p></header><div class=\"post-content\"><section class=\"info-panel highlight-card\"><h2>Resumen rápido</h2><ul class=\"info-list\"><li>No vendemos datos personales.</li><li>Los sorteos usan datos solo para contacto y validación de la inscripción.</li><li>Puedes solicitar la eliminación escribiendo a <a href=\"mailto:tql.tql@gmail.com\">tql.tql@gmail.com</a>.</li></ul></section><h2>1. Quiénes somos</h2><p>El sitio <strong>Inspetor BudGanja</strong> es un laboratorio digital de contenido educativo sobre cultivo vegetal. Contacto oficial: <a href=\"mailto:tql.tql@gmail.com\">tql.tql@gmail.com</a>.</p><h2>2. Datos recopilados</h2><h3>Sorteos (formulario interno)</h3><p>Cuando participas en un sorteo mediante el formulario del sitio, podemos recopilar:</p><ul><li>Nombre completo, CPF, correo electrónico y teléfono</li><li>Ciudad, estado e Instagram (opcional)</li><li>Fecha/hora de inscripción y premio elegido, si corresponde</li></ul><h3>Sorteos (Google Forms)</h3><p>Si el sorteo usa un formulario externo de Google, los datos son procesados por Google conforme a la <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener noreferrer\">política de privacidad de Google</a>. Consulta también la configuración de privacidad definida por el administrador del formulario.</p><h3>Navegación en el sitio</h3><p>El servidor puede registrar logs técnicos (IP, fecha, página accedida) para seguridad y diagnóstico. No usamos cookies de seguimiento publicitario.</p><h2>3. Finalidad del tratamiento</h2><ul><li>Validar inscripciones en sorteos (una por CPF/correo)</li><li>Contactar ganadores y responder dudas</li><li>Mantener el sitio seguro y funcional</li></ul><h2>4. Base legal (LGPD)</h2><p>El tratamiento se basa en el <strong>consentimiento</strong> (aceptación en el formulario del sorteo) y en el <strong>interés legítimo</strong> para la operación técnica del sitio, respetando siempre tus derechos.</p><h2>5. Conservación</h2><p>Los datos de sorteos se conservan durante el periodo necesario para realizar el sorteo, contactar al ganador y cumplir obligaciones legales. Después, pueden anonimizarse o eliminarse.</p><h2>6. Tus derechos</h2><p>Puedes solicitar:</p><ul><li>Confirmación y acceso a los datos</li><li>Corrección de datos incompletos o desactualizados</li><li>Eliminación de datos tratados con consentimiento</li><li>Revocación del consentimiento</li></ul><p>Envía solicitudes a <a href=\"mailto:tql.tql@gmail.com\">tql.tql@gmail.com</a> con el asunto <em>Privacidad — LGPD</em>.</p><h2>7. Seguridad</h2><p>Aplicamos medidas técnicas razonables (HTTPS en producción, acceso restringido al panel admin, contraseñas de entorno). Ningún sistema es 100% invulnerable; recomendamos no reutilizar contraseñas importantes en formularios públicos.</p><h2>8. Cambios</h2><p>Esta política puede actualizarse. La fecha de la última revisión aparece en el pie de página del sitio.</p><p class=\"privacy-updated\"><em>Última actualización: 26 de junio de 2026.</em></p><p class=\"section-cta-inline\"><a href=\"/sorteios/\" class=\"botao btn-inline\">Ver sorteos</a><a href=\"/info/contato.html\" class=\"botao admin-secondary btn-inline\">Contáctanos</a></p></div>"}},"equipamentos/index.html":{"en":{"title":"Equipment | Inspetor BudGanja","bodyHtml":"<h1 data-i18n=\"pages.equipment.title\">Equipment</h1><p class=\"secao-subtitulo\" style=\"margin-bottom: 40px;\" data-i18n-html=\"pages.equipment.subtitle\">Documented homemade cloning machines — choose based on your budget and number of cuttings. Materials from ordinary shops (pet shop, gardening, or light construction).</p><article class=\"item-lista item-lista--clonadora\"><img src=\"/imagens/clonadora.svg\" alt=\"Homemade 6-cutting cloning machine with an ice cream container\" loading=\"lazy\" data-i18n-alt=\"pages.equipment.cloner6Alt\"><div class=\"texto-item\"><h3 data-i18n=\"pages.equipment.cloner6Title\">6-cutting cloning machine</h3><p data-i18n-html=\"pages.equipment.cloner6Body\">Ice cream container, dish sponge, and air pump — bubbles in the water, <strong>24 hours a day</strong> until rooting. A <strong>low-cost</strong>, easy-to-assemble project.</p><a href=\"/equipamentos/clonadora-6-estacas.html\" class=\"botao\" data-i18n=\"pages.equipment.cloner6Cta\">View assembly guide</a></div></article><article class=\"item-lista item-lista--clonadora\" style=\"margin-top: 24px;\"><img src=\"/imagens/aeroclonadora.jpg\" alt=\"Homemade 12-cutting cloning machine with bucket and sprayers\" loading=\"lazy\" data-i18n-alt=\"pages.equipment.cloner12Alt\"><div class=\"texto-item\"><h3 data-i18n=\"pages.equipment.cloner12Title\">12-cutting cloning machine</h3><p data-i18n-html=\"pages.equipment.cloner12Body\">Bucket, submersible pump, and micro-sprayer kit — water sprayed on the roots, <strong>24 hours a day</strong> until transplanting. A <strong>moderate- to high-cost</strong> project.</p><a href=\"/equipamentos/clonadora-12-estacas.html\" class=\"botao\" data-i18n=\"pages.equipment.cloner12Cta\">View assembly guide</a></div></article><h2 class=\"category-title\" style=\"margin-top: 48px;\" data-i18n=\"pages.equipment.publications\">Equipment publications</h2><div class=\"container-cards publications-equipamentos\"><p class=\"empty-message\" data-i18n=\"pages.equipment.loading\">Loading publications...</p></div>"},"es":{"title":"Equipos | Inspetor BudGanja","bodyHtml":"<h1 data-i18n=\"pages.equipment.title\">Equipos</h1><p class=\"secao-subtitulo\" style=\"margin-bottom: 40px;\" data-i18n-html=\"pages.equipment.subtitle\">Clonadoras caseras documentadas — elige según el presupuesto y la cantidad de esquejes. Materiales de tienda común (pet shop, jardinería o construcción ligera).</p><article class=\"item-lista item-lista--clonadora\"><img src=\"/imagens/clonadora.svg\" alt=\"Clonadora casera de 6 esquejes con recipiente de helado\" loading=\"lazy\" data-i18n-alt=\"pages.equipment.cloner6Alt\"><div class=\"texto-item\"><h3 data-i18n=\"pages.equipment.cloner6Title\">Clonadora de 6 esquejes</h3><p data-i18n-html=\"pages.equipment.cloner6Body\">Recipiente de helado, esponja de cocina y bomba de aire — burbujas en el agua, <strong>24 horas al día</strong> hasta enraizar. Proyecto de <strong>bajo costo</strong> y montaje fácil.</p><a href=\"/equipamentos/clonadora-6-estacas.html\" class=\"botao\" data-i18n=\"pages.equipment.cloner6Cta\">Ver guía de montaje</a></div></article><article class=\"item-lista item-lista--clonadora\" style=\"margin-top: 24px;\"><img src=\"/imagens/aeroclonadora.jpg\" alt=\"Clonadora casera de 12 esquejes con cubeta y aspersores\" loading=\"lazy\" data-i18n-alt=\"pages.equipment.cloner12Alt\"><div class=\"texto-item\"><h3 data-i18n=\"pages.equipment.cloner12Title\">Clonadora de 12 esquejes</h3><p data-i18n-html=\"pages.equipment.cloner12Body\">Cubeta, bomba sumergible y kit de microaspersores — agua pulverizada sobre las raíces, <strong>24 horas al día</strong> hasta el trasplante. Proyecto de <strong>costo moderado a alto</strong>.</p><a href=\"/equipamentos/clonadora-12-estacas.html\" class=\"botao\" data-i18n=\"pages.equipment.cloner12Cta\">Ver guía de montaje</a></div></article><h2 class=\"category-title\" style=\"margin-top: 48px;\" data-i18n=\"pages.equipment.publications\">Publicaciones de equipos</h2><div class=\"container-cards publications-equipamentos\"><p class=\"empty-message\" data-i18n=\"pages.equipment.loading\">Cargando publicaciones...</p></div>"}},"info/apresentacao-unifesp.html":{"en":{"title":"UNIFESP Presentation | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><p class=\"article-eyebrow\">Presentation · 14th UNIFESP Course</p><h1>Inspetor BudGanja</h1><p class=\"page-intro\">A digital educational laboratory for Brazil's medicinal plants — independently developed by a student in the 14th Continuing Education Course in Medicinal Cannabis (UNIFESP / MovReCam).</p><p class=\"apresentacao-lead-links section-cta-inline\"><a href=\"https://inspetorbudganja.com.br/\" class=\"botao btn-inline\">Open the laboratory</a><a href=\"/biblioteca/unifesp/\" class=\"botao botao-outline btn-inline\">UNIFESP course hub</a></p></header><section class=\"info-panel apresentacao-author\" aria-labelledby=\"apresentacao-author-title\"><h2 id=\"apresentacao-author-title\">Presenter</h2><p class=\"info-panel-text\"><strong>Tiago Queiroz Loureiro</strong> — computer scientist focused on controlled-environment agriculture (CEA), automation, and agricultural IoT. Student in the 14th UNIFESP Course. Inspetor BudGanja is this work's public laboratory: bringing computational precision and botany together in accessible content and tools.</p><p class=\"section-cta-inline\"><a href=\"https://www.linkedin.com/in/tiago-queiroz-loureiro/\" class=\"botao botao-outline btn-inline\" target=\"_blank\" rel=\"noopener noreferrer\">LinkedIn</a><a href=\"mailto:tql.tql@gmail.com\" class=\"botao botao-outline btn-inline\">Email</a><a href=\"/info/contato.html\" class=\"botao botao-outline btn-inline\">Site contact</a></p></section><section class=\"info-panel apresentacao-channels\" aria-labelledby=\"apresentacao-channels-title\"><h2 id=\"apresentacao-channels-title\">Other communication channels</h2><p class=\"info-panel-text\">Besides the site, the laboratory publishes on YouTube and Spotify — and gathers the Inspector, <strong>MovReCam</strong>, and <strong>CANABinALL</strong> archives in the <a href=\"/videos/\">video hub</a> for in-page review. Supplementary educational content, <strong>independent</strong> from the UNIFESP course.</p><p class=\"section-cta-inline\"><a href=\"/videos/\" class=\"botao botao-outline btn-inline apresentacao-channel-btn\">Videos</a><a href=\"https://open.spotify.com/show/033yuLDWnN84xOcfHyJ1FZ\" class=\"botao botao-outline btn-inline apresentacao-channel-btn\" target=\"_blank\" rel=\"noopener noreferrer\">Spotify</a></p></section><section class=\"apresentacao-story\" aria-labelledby=\"apresentacao-what-title\"><h2 id=\"apresentacao-what-title\">What the project is</h2><p>A public web platform dedicated to medicinal plants, responsible cannabis literacy, and practical cultivation documentation. Content is educational, multilingual (English, Portuguese, and Spanish), and makes ethical limitations explicit: <strong>it does not replace medical, pharmaceutical, or legal guidance</strong>, nor SIEX or official UNIFESP classes.</p></section><section class=\"info-panel\" aria-labelledby=\"apresentacao-unifesp-title\"><h2 id=\"apresentacao-unifesp-title\">Connection with the UNIFESP course</h2><ul class=\"info-list\"><li><a href=\"/biblioteca/unifesp/\">14th course hub</a> — practical summary, SIEX, workload, and study paths.</li><li><a href=\"/posts/post-inspecao-curso-unifesp-cannabis-medicinal.html\">Program inspection</a> — independent editorial audit of the extension course.</li><li>Homepage and video-hub highlights for <strong>MovReCam</strong> and <strong>CANABinALL</strong>.</li><li>Goal: expand the reach of continuing education and connect academic content with botanical profiles and practical tools — <strong>with no affiliation</strong> to UNIFESP or MovReCam.</li></ul></section><section class=\"info-panel\" aria-labelledby=\"apresentacao-legado-title\"><h2 id=\"apresentacao-legado-title\">Credit to the origins</h2><p class=\"info-panel-text\">The laboratory documents, from public sources and with explicit credit, the pastoral and scientific roots of the ecosystem the course continues. This is not hagiography: it is the BudGanja method — <strong>credit where credit is due</strong>.</p><ul class=\"info-list\"><li><a href=\"/posts/post-inspecao-padre-ticao.html\">Father Ticão</a> — community / MovReCam origin on São Paulo's periphery.</li><li><a href=\"/posts/post-inspecao-elisaldo-carlini.html\">Prof. Elisaldo Carlini</a> — pioneer of cannabis pharmacology in Brazil; CEBRID; CANABinALL dedication.</li><li><a href=\"/biblioteca/inspecoes/#inspecoes-pessoas\">Hub · Legacy</a> and <a href=\"/biblioteca/inspecoes/#inspecoes-sugestoes\">suggestions queue</a> — upcoming reports (e.g. Solange Nappo, Eliana Rodrigues) kept separate from published inspections.</li></ul></section><section class=\"apresentacao-modules\" aria-labelledby=\"apresentacao-modules-title\"><h2 id=\"apresentacao-modules-title\">Laboratory modules</h2><ol class=\"apresentacao-modules-list\"><li><a href=\"/plantas/\"><strong>Herbal plants</strong></a> — around 29 educational profiles (common/scientific name, traditional uses, used parts, care).</li><li><a href=\"/cultivo/\"><strong>Research journal</strong></a> — records by species (stages, notes, plan), including from the catalog.</li><li><a href=\"/biblioteca/inspecoes/\"><strong>Inspections</strong></a> — legacy, channels, courses, scientific articles, and equipment, with a verifiable method.</li><li><a href=\"/videos/\"><strong>Video hub</strong></a> — in-site player with channel and series filters (XIV lectures, Concepts, Sacred Plants).</li><li><a href=\"/calculadoras/\"><strong>Browser tools</strong></a> — VPD, DLI, pH/EC, light meter, super soil, and other utilities.</li><li><a href=\"/comunidade/\"><strong>Community</strong></a>, <a href=\"/equipamentos/\">documented equipment</a>, <a href=\"/radio/\">BudGanja Radio</a>, and <a href=\"https://open.spotify.com/show/033yuLDWnN84xOcfHyJ1FZ\" target=\"_blank\" rel=\"noopener noreferrer\">Spotify podcast</a> as study aids.</li></ol></section><div class=\"section-grid apresentacao-grid\"><section class=\"info-panel\"><h3>What this project is</h3><ul class=\"info-list\"><li>An independent educational initiative by a course student.</li><li>A digital space for responsible study, documentation, and sharing.</li><li>A bridge between continuing education, the botanical catalog, and laboratory practice.</li></ul></section><section class=\"info-panel\"><h3>What this project is not</h3><ul class=\"info-list\"><li>It is not a commercial product affiliated with UNIFESP.</li><li>It does not replace SIEX enrollment, official classes, or the course certificate.</li><li>It does not provide clinical, pharmaceutical, or legal advice.</li></ul></section></div><section class=\"info-panel apresentacao-ask\" aria-labelledby=\"apresentacao-ask-title\"><h2 id=\"apresentacao-ask-title\">Request to the coordination</h2><p class=\"info-panel-text\">I am available for a brief demonstration (online or in person), to receive feedback from the coordination and, if appropriate, to align mentions, official links, or citation practices for the 14th UNIFESP Course.</p><p class=\"section-cta-inline\"><a href=\"mailto:tql.tql@gmail.com?subject=Apresentação%20Inspetor%20BudGanja%20—%20XIV%20Curso%20UNIFESP\" class=\"botao btn-inline\">Write to the author</a><a href=\"/info/sobre.html\" class=\"botao botao-outline btn-inline\">About the laboratory</a></p></section><section class=\"apresentacao-share info-panel\" aria-labelledby=\"apresentacao-share-title\"><h2 id=\"apresentacao-share-title\">Presentation link</h2><p class=\"info-panel-text\">You can share this page directly:</p><p class=\"apresentacao-url\"><a href=\"https://inspetorbudganja.com.br/info/apresentacao-unifesp.html\">https://inspetorbudganja.com.br/info/apresentacao-unifesp.html</a></p></section>"},"es":{"title":"Presentación UNIFESP | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><p class=\"article-eyebrow\">Presentación · XIV Curso UNIFESP</p><h1>Inspetor BudGanja</h1><p class=\"page-intro\">Laboratorio digital educativo de plantas medicinales de Brasil — desarrollado de manera independiente por un alumno del XIV Curso de Extensión en Cannabis Medicinal (UNIFESP / MovReCam).</p><p class=\"apresentacao-lead-links section-cta-inline\"><a href=\"https://inspetorbudganja.com.br/\" class=\"botao btn-inline\">Abrir el laboratorio</a><a href=\"/biblioteca/unifesp/\" class=\"botao botao-outline btn-inline\">Hub del curso UNIFESP</a></p></header><section class=\"info-panel apresentacao-author\" aria-labelledby=\"apresentacao-author-title\"><h2 id=\"apresentacao-author-title\">Quién presenta</h2><p class=\"info-panel-text\"><strong>Tiago Queiroz Loureiro</strong> — científico de la computación, enfocado en ambientes controlados (CEA), automatización e IoT agrícola. Alumno del XIV Curso UNIFESP. Inspetor BudGanja es el laboratorio público de este trabajo: unir precisión computacional y botánica en herramientas y contenido accesibles.</p><p class=\"section-cta-inline\"><a href=\"https://www.linkedin.com/in/tiago-queiroz-loureiro/\" class=\"botao botao-outline btn-inline\" target=\"_blank\" rel=\"noopener noreferrer\">LinkedIn</a><a href=\"mailto:tql.tql@gmail.com\" class=\"botao botao-outline btn-inline\">Correo electrónico</a><a href=\"/info/contato.html\" class=\"botao botao-outline btn-inline\">Contacto en el sitio</a></p></section><section class=\"info-panel apresentacao-channels\" aria-labelledby=\"apresentacao-channels-title\"><h2 id=\"apresentacao-channels-title\">Otros canales de comunicación</h2><p class=\"info-panel-text\">Además del sitio, el laboratorio publica en YouTube y Spotify — y reúne en el <a href=\"/videos/\">hub de videos</a> el acervo del Inspector, de <strong>MovReCam</strong> y de <strong>CANABinALL</strong> para revisión in-page. Contenido educativo complementario, <strong>independiente</strong> del curso UNIFESP.</p><p class=\"section-cta-inline\"><a href=\"/videos/\" class=\"botao botao-outline btn-inline apresentacao-channel-btn\">Videos</a><a href=\"https://open.spotify.com/show/033yuLDWnN84xOcfHyJ1FZ\" class=\"botao botao-outline btn-inline apresentacao-channel-btn\" target=\"_blank\" rel=\"noopener noreferrer\">Spotify</a></p></section><section class=\"apresentacao-story\" aria-labelledby=\"apresentacao-what-title\"><h2 id=\"apresentacao-what-title\">Qué es el proyecto</h2><p>Plataforma web pública dedicada a plantas medicinales, alfabetización cannábica responsable y documentación práctica de cultivo. El contenido es educativo, multilingüe (inglés, portugués y español) y deja claros sus límites éticos: <strong>no sustituye orientación médica, farmacéutica ni jurídica</strong>, ni SIEX o las clases oficiales de UNIFESP.</p></section><section class=\"info-panel\" aria-labelledby=\"apresentacao-unifesp-title\"><h2 id=\"apresentacao-unifesp-title\">Vínculo con el curso UNIFESP</h2><ul class=\"info-list\"><li><a href=\"/biblioteca/unifesp/\">Hub del XIV curso</a> — resumen práctico, SIEX, carga horaria y rutas de estudio.</li><li><a href=\"/posts/post-inspecao-curso-unifesp-cannabis-medicinal.html\">Inspección del programa</a> — auditoría editorial independiente del curso de extensión.</li><li>Destacado en la página inicial y en el hub de videos para <strong>MovReCam</strong> y <strong>CANABinALL</strong>.</li><li>Objetivo: ampliar el alcance de la formación de extensión y cruzar contenido académico con fichas botánicas y herramientas prácticas — <strong>sin afiliación</strong> con la UNIFESP o el MovReCam.</li></ul></section><section class=\"info-panel\" aria-labelledby=\"apresentacao-legado-title\"><h2 id=\"apresentacao-legado-title\">Crédito a los orígenes</h2><p class=\"info-panel-text\">El laboratorio documenta, con fuentes públicas y mérito explícito, las raíces pastorales y científicas del ecosistema que el curso prolonga. No es hagiografía: es el método BudGanja — <strong>crédito a quien lo merece</strong>.</p><ul class=\"info-list\"><li><a href=\"/posts/post-inspecao-padre-ticao.html\">Padre Ticão</a> — origen comunitario / MovReCam en la periferia de São Paulo.</li><li><a href=\"/posts/post-inspecao-elisaldo-carlini.html\">Prof. Elisaldo Carlini</a> — pionero de la farmacología del cannabis en Brasil; CEBRID; dedicación del CANABinALL.</li><li><a href=\"/biblioteca/inspecoes/#inspecoes-pessoas\">Hub · Legado</a> y <a href=\"/biblioteca/inspecoes/#inspecoes-sugestoes\">cola de sugerencias</a> — próximos informes (p. ej. Solange Nappo, Eliana Rodrigues) separados de las inspecciones ya publicadas.</li></ul></section><section class=\"apresentacao-modules\" aria-labelledby=\"apresentacao-modules-title\"><h2 id=\"apresentacao-modules-title\">Módulos del laboratorio</h2><ol class=\"apresentacao-modules-list\"><li><a href=\"/plantas/\"><strong>Plantas fitoterapéuticas</strong></a> — cerca de 29 fichas educativas.</li><li><a href=\"/cultivo/\"><strong>Diario de investigaciones</strong></a> — registro por especie.</li><li><a href=\"/biblioteca/inspecoes/\"><strong>Inspecciones</strong></a> — legado, canales, cursos, artículos científicos y equipos, con método verificable.</li><li><a href=\"/videos/\"><strong>Hub de videos</strong></a> — reproductor in-site con filtros por canal y serie (clases XIV, Conceptos, Plantas Sagradas).</li><li><a href=\"/calculadoras/\"><strong>Herramientas en el navegador</strong></a> — VPD, DLI, pH/EC, luxómetro, super suelo y más.</li><li><a href=\"/comunidade/\"><strong>Comunidad</strong></a>, <a href=\"/equipamentos/\">equipos documentados</a>, <a href=\"/radio/\">BudGanja Radio</a> y <a href=\"https://open.spotify.com/show/033yuLDWnN84xOcfHyJ1FZ\" target=\"_blank\" rel=\"noopener noreferrer\">podcast en Spotify</a> como apoyo al estudio.</li></ol></section><div class=\"section-grid apresentacao-grid\"><section class=\"info-panel\"><h3>Qué es este proyecto</h3><ul class=\"info-list\"><li>Iniciativa educativa independiente de un alumno del curso.</li><li>Espacio digital para estudiar, documentar y compartir responsablemente.</li><li>Puente entre extensión académica, catálogo botánico y práctica de laboratorio.</li></ul></section><section class=\"info-panel\"><h3>Qué no es este proyecto</h3><ul class=\"info-list\"><li>No es un producto comercial afiliado a UNIFESP.</li><li>No sustituye inscripción SIEX, clases oficiales ni certificado del curso.</li><li>No brinda asesoramiento clínico, farmacéutico ni jurídico.</li></ul></section></div><section class=\"info-panel apresentacao-ask\" aria-labelledby=\"apresentacao-ask-title\"><h2 id=\"apresentacao-ask-title\">Solicitud a la coordinación</h2><p class=\"info-panel-text\">Estoy disponible para una demostración breve (en línea o presencial), para recibir críticas de la coordinación y, si tiene sentido, alinear menciones, enlaces oficiales o buenas prácticas de cita para el XIV Curso UNIFESP.</p><p class=\"section-cta-inline\"><a href=\"mailto:tql.tql@gmail.com?subject=Apresentação%20Inspetor%20BudGanja%20—%20XIV%20Curso%20UNIFESP\" class=\"botao btn-inline\">Escribir al autor</a><a href=\"/info/sobre.html\" class=\"botao botao-outline btn-inline\">Acerca del laboratorio</a></p></section><section class=\"apresentacao-share info-panel\" aria-labelledby=\"apresentacao-share-title\"><h2 id=\"apresentacao-share-title\">Enlace de esta presentación</h2><p class=\"info-panel-text\">Puedes compartir esta página directamente:</p><p class=\"apresentacao-url\"><a href=\"https://inspetorbudganja.com.br/info/apresentacao-unifesp.html\">https://inspetorbudganja.com.br/info/apresentacao-unifesp.html</a></p></section>"}},"biblioteca/unifesp/index.html":{"en":{"title":"UNIFESP Course | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><p class=\"article-eyebrow\">Education · UNIFESP</p><h1 data-i18n=\"pages.unifesp.title\">14th Course — Medicinal Cannabis sativa L.</h1><p class=\"page-intro\" data-i18n=\"pages.unifesp.subtitle\">A continuing-education course from the Federal University of São Paulo (UNIFESP), in partnership with MovReCam — a reference in democratic cannabis education. This hub summarizes the essentials and connects the program to plant profiles and the practical Inspetor BudGanja laboratory.</p></header><aside class=\"unifesp-disclaimer\" role=\"note\"><strong>Educational content.</strong> It does not replace medical, pharmaceutical, or legal guidance. Always confirm dates, openings, and rules in the official SIEX catalog before enrolling. No institutional affiliation with UNIFESP or MovReCam.</aside><section class=\"info-panel unifesp-cta-panel\"><h2>Enrollment and review</h2><p>Enroll through SIEX (code 30063) and read the complete editorial review of the program.</p><div class=\"home-pillar-actions\"><a class=\"botao botao-home\" href=\"https://siex.siiu.unifesp.br/catalogo-siex/30063/mais-info\" rel=\"noopener noreferrer\" target=\"_blank\">SIEX enrollment</a><a class=\"botao botao-home botao-home--secondary\" href=\"/posts/post-inspecao-curso-unifesp-cannabis-medicinal.html\">Complete review</a></div></section><section class=\"info-panel\"><h2>Practical summary (14th edition)</h2><div class=\"table-wrap\"><table class=\"unifesp-table\"><tbody><tr><th scope=\"row\">Institution</th><td>UNIFESP · university extension · Health area</td></tr><tr><th scope=\"row\">Partnership</th><td>MovReCam</td></tr><tr><th scope=\"row\">Openings</th><td>10&nbsp;000</td></tr><tr><th scope=\"row\">Format</th><td>Online — classes on YouTube</td></tr><tr><th scope=\"row\">Workload</th><td>57&nbsp;h of theory</td></tr><tr><th scope=\"row\">Period (14th)</th><td>06/16/2026 to 11/12/2026</td></tr><tr><th scope=\"row\">Schedule</th><td>Tuesdays and Thursdays, from 7:30 p.m.</td></tr><tr><th scope=\"row\">Requirement</th><td>At least 18 years old</td></tr><tr><th scope=\"row\">Fees</th><td>Enrollment and certificate are free</td></tr><tr><th scope=\"row\">Certificate</th><td>≥&nbsp;75% attendance · issued through SIEX</td></tr><tr><th scope=\"row\">Contact</th><td><a href=\"mailto:curso.cannabismedicinal@unifesp.br\">curso.cannabismedicinal@unifesp.br</a></td></tr></tbody></table></div><p class=\"unifesp-note\">Dates and rules may change — official source: <a href=\"https://siex.siiu.unifesp.br/catalogo-siex/30063/mais-info\" rel=\"noopener noreferrer\" target=\"_blank\">SIEX catalog 30063</a>.</p></section><section class=\"info-panel\"><h2>How to use it with the laboratory</h2><ul class=\"info-list\"><li><a href=\"/plantas/cannabis-sativa/\">Cannabis sativa profile</a> — medicinal context and catalog tags.</li><li><a href=\"/plantas/\">Herbal plants</a> — Brazilian species and traditional uses related to the curriculum.</li><li><a href=\"/biblioteca/inspecoes/\">Reviews</a> — cultivation, cloning, and indoor environments with field metrics.</li><li><a href=\"/calculadoras/\">Tools</a> — VPD, DLI, EC, and light meter.</li><li><a href=\"/cultivo/\">Research journal</a> — document experiments structurally.</li></ul></section><section class=\"info-panel\"><h2>Official links</h2><ul class=\"info-list\"><li><a href=\"https://siex.siiu.unifesp.br/catalogo-siex/30063/mais-info\" rel=\"noopener noreferrer\" target=\"_blank\">SIEX — course profile (30063)</a></li><li><a href=\"https://www.unifesp.br/\" rel=\"noopener noreferrer\" target=\"_blank\">UNIFESP Portal</a></li><li><a href=\"https://www.youtube.com/movrecam\" rel=\"noopener noreferrer\" target=\"_blank\">MovReCam channel (YouTube)</a></li><li><a href=\"/posts/post-inspecao-curso-unifesp-cannabis-medicinal.html\">Inspetor BudGanja review</a></li></ul></section>"},"es":{"title":"Curso UNIFESP | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><p class=\"article-eyebrow\">Formación · UNIFESP</p><h1 data-i18n=\"pages.unifesp.title\">XIV Curso — Cannabis sativa L. medicinal</h1><p class=\"page-intro\" data-i18n=\"pages.unifesp.subtitle\">Curso de extensión de la Universidad Federal de São Paulo (UNIFESP), en alianza con MovReCam — referencia en educación cannábica democrática. Este hub resume lo esencial y conecta el programa con fichas de plantas y el laboratorio práctico de Inspetor BudGanja.</p></header><aside class=\"unifesp-disclaimer\" role=\"note\"><strong>Contenido educativo.</strong> No sustituye orientación médica, farmacéutica ni jurídica. Confirma siempre fechas, cupos y reglas en el catálogo oficial SIEX antes de inscribirte. Sin vínculo institucional con UNIFESP ni MovReCam.</aside><section class=\"info-panel unifesp-cta-panel\"><h2>Inscripción e inspección</h2><p>Inscríbete en SIEX (código 30063) y lee la auditoría editorial completa del programa.</p><div class=\"home-pillar-actions\"><a class=\"botao botao-home\" href=\"https://siex.siiu.unifesp.br/catalogo-siex/30063/mais-info\" rel=\"noopener noreferrer\" target=\"_blank\">Inscripción SIEX</a><a class=\"botao botao-home botao-home--secondary\" href=\"/posts/post-inspecao-curso-unifesp-cannabis-medicinal.html\">Inspección completa</a></div></section><section class=\"info-panel\"><h2>Resumen práctico (XIV edición)</h2><div class=\"table-wrap\"><table class=\"unifesp-table\"><tbody><tr><th scope=\"row\">Institución</th><td>UNIFESP · extensión universitaria · área Salud</td></tr><tr><th scope=\"row\">Alianza</th><td>MovReCam</td></tr><tr><th scope=\"row\">Cupos</th><td>10&nbsp;000</td></tr><tr><th scope=\"row\">Modalidad</th><td>A distancia — clases en YouTube</td></tr><tr><th scope=\"row\">Carga horaria</th><td>57&nbsp;h teóricas</td></tr><tr><th scope=\"row\">Período (XIV)</th><td>16/06/2026 a 12/11/2026</td></tr><tr><th scope=\"row\">Horario</th><td>Martes y jueves, desde las 19:30</td></tr><tr><th scope=\"row\">Requisito</th><td>Mayor de 18 años</td></tr><tr><th scope=\"row\">Tarifas</th><td>Inscripción y certificado gratuitos</td></tr><tr><th scope=\"row\">Certificado</th><td>≥&nbsp;75% de asistencia · emisión en SIEX</td></tr><tr><th scope=\"row\">Contacto</th><td><a href=\"mailto:curso.cannabismedicinal@unifesp.br\">curso.cannabismedicinal@unifesp.br</a></td></tr></tbody></table></div><p class=\"unifesp-note\">Los plazos y reglas pueden cambiar — fuente oficial: <a href=\"https://siex.siiu.unifesp.br/catalogo-siex/30063/mais-info\" rel=\"noopener noreferrer\" target=\"_blank\">catálogo SIEX 30063</a>.</p></section><section class=\"info-panel\"><h2>Cómo usarlo con el laboratorio</h2><ul class=\"info-list\"><li><a href=\"/plantas/cannabis-sativa/\">Ficha Cannabis sativa</a> — contexto medicinal y etiquetas del catálogo.</li><li><a href=\"/plantas/\">Plantas fitoterapéuticas</a> — especies brasileñas y usos tradicionales relacionados con el programa.</li><li><a href=\"/biblioteca/inspecoes/\">Inspecciones</a> — cultivo, clonación y ambiente interior con métricas de campo.</li><li><a href=\"/calculadoras/\">Herramientas</a> — VPD, DLI, EC y luxómetro.</li><li><a href=\"/cultivo/\">Diario de investigaciones</a> — documentar experiencias estructuradamente.</li></ul></section><section class=\"info-panel\"><h2>Enlaces oficiales</h2><ul class=\"info-list\"><li><a href=\"https://siex.siiu.unifesp.br/catalogo-siex/30063/mais-info\" rel=\"noopener noreferrer\" target=\"_blank\">SIEX — ficha del curso (30063)</a></li><li><a href=\"https://www.unifesp.br/\" rel=\"noopener noreferrer\" target=\"_blank\">Portal UNIFESP</a></li><li><a href=\"https://www.youtube.com/movrecam\" rel=\"noopener noreferrer\" target=\"_blank\">Canal MovReCam (YouTube)</a></li><li><a href=\"/posts/post-inspecao-curso-unifesp-cannabis-medicinal.html\">Inspección Inspetor BudGanja</a></li></ul></section>"}},"equipamentos/clonadora-6-estacas.html":{"en":{"title":"Guide: 6-cutting cloning machine | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><a href=\"/equipamentos/\" class=\"voltar-link\">← Back to Equipment</a><p class=\"article-eyebrow\">Equipment</p><p class=\"manual-variant-badge\">6 cuttings</p><h1>Ice-cream-container cloning machine</h1><div class=\"meta-info\">Author: Inspetor BudGanja · Difficulty: Easy · Cost: very low</div></header><div class=\"post-content\"><div class=\"highlight\"><h2>One-sentence summary</h2><p>Ice cream container + lid with <strong>6 holes</strong> + <strong>dish sponges</strong> as supports + <strong>aquarium air pump on 24 h</strong> in water until roots appear. <strong>No clock, timer, or complicated part.</strong></p></div><figure class=\"relatorio-figure\"><img src=\"/imagens/clonadora.svg\" alt=\"Diagram of the 6-cutting cloning machine\" loading=\"lazy\"><figcaption>6-cutting cloning machine — ice cream container and air-bubble oxygenation.</figcaption></figure><h2>What you will build</h2><p>An ice cream container becomes the water tank. Up to <strong>6 cuttings</strong> fit through the lid, held by dish sponges. The air pump stays in the water all the time. Bubbles oxygenate and keep moisture around the base of the cuttings.</p><h2 id=\"materiais\">Materials</h2><div class=\"highlight\"><ul><li><strong>1 ice cream container</strong> with lid (2 L works well)</li><li><strong>1 small aquarium air pump</strong> (air bubbles only)</li><li><strong>Dish sponges</strong> — 1 pack</li><li><strong>Clean water</strong></li><li><strong>Hole punch or scissors</strong></li><li><strong>Rooting gel</strong> (optional)</li></ul></div><h2>Assembly — step by step</h2><h3>Step 1 — Prepare the container</h3><ol><li>Wash the container and lid.</li><li>Fill it with water to <strong>two fingers below the lid</strong>.</li><li>Place the air pump <strong>in the water</strong>, at the bottom.</li></ol><h3>Step 2 — 6 holes in the lid</h3><ol><li>Mark <strong>6 points</strong> on the lid.</li><li>Make <strong>6 round holes</strong> to fit the sponge.</li></ol><h3>Step 3 — Sponges as supports</h3><ol><li>Cut <strong>6 sponge discs</strong>, larger than each hole.</li><li>Cut each disc <strong>halfway through</strong> and fit the cutting stem in the middle.</li></ol><h3>Step 4 — Cuttings and pump</h3><ol><li>Place cuttings in the holes; the base stays near the bubbles without being deeply submerged.</li><li>Leave the pump on <strong>24 hours a day</strong> — <strong>no timer</strong> until roots emerge.</li></ol><h2>Care and timing</h2><p>Allow <strong>7 to 14 days</strong> for 2–3 cm roots. Change water if it becomes cloudy. Ideal temperature: 20–26 °C.</p><p class=\"manual-variant-back\"><a href=\"/equipamentos/clonadora-12-estacas.html\">See also: 12-cutting cloning machine (bucket with sprayers) →</a></p></div>"},"es":{"title":"Guía: Clonadora de 6 esquejes | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><a href=\"/equipamentos/\" class=\"voltar-link\">← Volver a Equipos</a><p class=\"article-eyebrow\">Equipos</p><p class=\"manual-variant-badge\">6 esquejes</p><h1>Clonadora con recipiente de helado</h1><div class=\"meta-info\">Autor: Inspetor BudGanja · Dificultad: Fácil · Costo: muy bajo</div></header><div class=\"post-content\"><div class=\"highlight\"><h2>Resumen en una frase</h2><p>Recipiente de helado + tapa con <strong>6 agujeros</strong> + <strong>esponjas de cocina</strong> como soporte + <strong>bomba de acuario encendida 24 h</strong> en el agua hasta que aparezcan las raíces. <strong>Sin reloj, temporizador ni pieza complicada.</strong></p></div><figure class=\"relatorio-figure\"><img src=\"/imagens/clonadora.svg\" alt=\"Esquema de la clonadora de 6 esquejes\" loading=\"lazy\"><figcaption>Clonadora de 6 esquejes — recipiente de helado y oxigenación por burbujas de aire.</figcaption></figure><h2>Qué vas a montar</h2><p>Un recipiente de helado se convierte en tanque de agua. En la tapa entran hasta <strong>6 esquejes</strong> sujetos con esponja de cocina. La bomba de aire queda en el agua todo el tiempo. Las burbujas oxigenan y mantienen humedad en la base de los esquejes.</p><h2 id=\"materiais\">Materiales</h2><div class=\"highlight\"><ul><li><strong>1 recipiente de helado</strong> con tapa (2 L funciona bien)</li><li><strong>1 bomba de aire de acuario</strong> pequeña</li><li><strong>Esponjas de cocina</strong> — 1 paquete</li><li><strong>Agua</strong> limpia</li><li><strong>Perforador o tijeras</strong></li><li><strong>Gel de enraizamiento</strong> (opcional)</li></ul></div><h2>Montaje — paso a paso</h2><h3>Paso 1 — Preparar el recipiente</h3><ol><li>Lava el recipiente y la tapa.</li><li>Llénalo con agua hasta <strong>dos dedos por debajo de la tapa</strong>.</li><li>Coloca la bomba <strong>dentro del agua</strong>, al fondo.</li></ol><h3>Paso 2 — 6 agujeros en la tapa</h3><ol><li>Marca <strong>6 puntos</strong> en la tapa.</li><li>Abre <strong>6 agujeros redondos</strong> para encajar la esponja.</li></ol><h3>Paso 3 — Esponjas como soporte</h3><ol><li>Corta <strong>6 discos</strong> de esponja, mayores que cada agujero.</li><li>Corta cada disco <strong>hasta la mitad</strong> y encaja el tallo del esqueje en el centro.</li></ol><h3>Paso 4 — Esquejes y bomba</h3><ol><li>Coloca los esquejes en los agujeros; la base queda cerca de las burbujas, sin sumergirse profundamente.</li><li>Enciende la bomba <strong>24 horas al día</strong> — <strong>sin temporizador</strong> hasta que salgan raíces.</li></ol><h2>Cuidados y plazo</h2><p>Entre <strong>7 y 14 días</strong> para raíces de 2–3 cm. Cambia el agua si se enturbia. Temperatura ideal: 20–26 °C.</p><p class=\"manual-variant-back\"><a href=\"/equipamentos/clonadora-12-estacas.html\">Ver también: clonadora de 12 esquejes (cubeta con aspersores) →</a></p></div>"}},"equipamentos/clonadora-12-estacas.html":{"en":{"title":"Guide: 12-cutting cloning machine | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><a href=\"/equipamentos/\" class=\"voltar-link\">← Back to Equipment</a><p class=\"article-eyebrow\">Equipment</p><p class=\"manual-variant-badge manual-variant-badge--premium\">12 cuttings</p><h1>Bucket-and-sprayer cloning machine</h1><div class=\"meta-info\">Author: Inspetor BudGanja · Difficulty: Medium · Cost: moderate to high</div></header><div class=\"post-content\"><div class=\"highlight\"><h2>One-sentence summary</h2><p><strong>Bucket</strong> with a perforated lid + <strong>submersible aquarium pump</strong> (better line, e.g., Arco-Íris) + <strong>irrigation micro-sprayer kit</strong> + <strong>felt mat</strong> in the holes — water is <strong>sprayed onto roots 24 h</strong> until rooting and transplanting.</p></div><figure class=\"relatorio-figure relatorio-figure--hero\"><img src=\"/imagens/aeroclonadora.jpg\" alt=\"12-cutting cloning machine with bucket and sprayers\" loading=\"lazy\"><figcaption>12-cutting cloning machine — bucket, submersible pump, and continuous root spraying.</figcaption></figure><h2>What you will build</h2><p>Unlike the container version, water <strong>does not sit still with bubbles</strong> — a <strong>submersible pump</strong> draws water from the bucket bottom and sends it to <strong>micro-sprayers</strong> that spray the cutting bases continuously. The lid holds up to <strong>12 cuttings</strong> in <strong>felt</strong> discs.</p><h2 id=\"materiais\">Materials</h2><div class=\"highlight\"><ul><li><strong>1 rigid bucket</strong> with lid (10–20 L; use good quality)</li><li><strong>1 submersible aquarium pump</strong> (e.g., Arco-Íris or equivalent — water pump, not only air)</li><li><strong>Sprayer kit</strong> for irrigation (micro-sprayers + hoses)</li><li><strong>Felt mat</strong> (cut into discs)</li><li><strong>Clean water</strong></li><li><strong>Hole punch, scissors, or utility knife</strong></li><li><strong>Rooting gel</strong> (optional)</li></ul></div><p class=\"field-hint\">Everything can be bought in a regular store: pet shop, light construction supplier, or market. The submersible pump and bucket cost more than the ice cream container.</p><h2>Assembly — step by step</h2><h3>Step 1 — Prepare the bucket</h3><ol><li>Wash the bucket and lid well.</li><li>Place the <strong>submersible pump</strong> at the bottom.</li><li>Add <strong>a little water</strong> — only enough for the pump and sprayer to work.</li></ol><h3>Step 2 — Cut the lid and round holes</h3><ol><li>Mark up to <strong>12 points</strong> on the lid, 15–20 cm apart.</li><li><strong>Cut round holes</strong>, one for each cutting.</li><li>Each hole must fit a felt disc that holds the stem.</li></ol><h3>Step 3 — Felt as support</h3><ol><li>Cut the <strong>felt mat</strong> into <strong>12 discs</strong> slightly larger than the holes.</li><li>Make a halfway cut in each disc.</li><li>Fit the cutting stem into the felt and press it into the lid hole.</li></ol><h3>Step 4 — Install the sprayer kit</h3><ol><li>Connect the pump outlet to the <strong>irrigation-kit hose</strong>.</li><li>Point the <strong>micro-sprayers</strong> at the <strong>base of the cuttings</strong>.</li><li>Secure hoses to the lid or bucket sides.</li><li>Run the pump cable through the lid or side.</li></ol><h3>Step 5 — Cuttings and operation</h3><ol><li>Insert cuttings into felt supports, with the base near the spray.</li><li>Close the lid.</li><li>Leave the pump on <strong>24 hours a day</strong> — <strong>no timer</strong>.</li><li>Water sprays the roots until transplanting.</li></ol><h2>How to tell it is correct</h2><ul><li>You see or hear <strong>continuous spraying</strong> in the root zone.</li><li>The pump stays <strong>submerged</strong> — never run it dry.</li><li>Cuttings stay firm in the felt and moist at the base.</li><li>Water remains low; refill if it evaporates.</li></ul><h2>How long until roots emerge?</h2><p>Generally <strong>7 to 14 days</strong>, as with the 6-cutting version. When roots are <strong>2 to 3 cm</strong>, transplant. Keep spraying until then.</p><h2>Care</h2><ul><li><strong>Water:</strong> change every 5–7 days or if cloudy or smelly.</li><li><strong>Temperature:</strong> 20–26 °C; avoid direct sun.</li><li><strong>Sprayers:</strong> clean if clogged.</li><li><strong>Felt:</strong> replace if it rots or smells.</li></ul><h2>Common problems</h2><p><strong>Pump does not spray:</strong> water level too low, clogged sprayer, or loose hose.</p><p><strong>Cutting wilting:</strong> weak spray, excessive heat, or loose felt support.</p><p><strong>Odorous water:</strong> replace immediately and clean the bucket.</p><div class=\"highlight\"><p style=\"margin:0;\"><strong>Quick list:</strong> lidded bucket · submersible aquarium pump · micro-sprayer kit · felt mat · water · punch/scissors · rooting gel (optional).</p></div><p class=\"manual-variant-back\"><a href=\"/equipamentos/clonadora-6-estacas.html\">← See also: 6-cutting cloning machine (ice cream container)</a></p></div>"},"es":{"title":"Guía: Clonadora de 12 esquejes | Inspetor BudGanja","bodyHtml":"<header class=\"article-header\"><a href=\"/equipamentos/\" class=\"voltar-link\">← Volver a Equipos</a><p class=\"article-eyebrow\">Equipos</p><p class=\"manual-variant-badge manual-variant-badge--premium\">12 esquejes</p><h1>Clonadora con cubeta y aspersores</h1><div class=\"meta-info\">Autor: Inspetor BudGanja · Dificultad: Media · Costo: moderado a alto</div></header><div class=\"post-content\"><div class=\"highlight\"><h2>Resumen en una frase</h2><p><strong>Cubeta</strong> con tapa perforada + <strong>bomba de acuario sumergible</strong> + <strong>kit de microaspersores</strong> + <strong>tapete de fieltro</strong> en los agujeros — el agua se <strong>pulveriza sobre las raíces 24 h</strong> hasta enraizar y trasplantar.</p></div><figure class=\"relatorio-figure relatorio-figure--hero\"><img src=\"/imagens/aeroclonadora.jpg\" alt=\"Clonadora de 12 esquejes con cubeta y aspersión\" loading=\"lazy\"><figcaption>Clonadora de 12 esquejes — cubeta, bomba sumergible y aspersión continua en las raíces.</figcaption></figure><h2>Qué vas a montar</h2><p>A diferencia de la versión con recipiente, el agua <strong>no queda quieta con burbujas</strong> — una <strong>bomba sumergible</strong> la lleva desde el fondo de la cubeta hasta <strong>microaspersores</strong> que rocían continuamente las bases. La tapa recibe hasta <strong>12 esquejes</strong> sujetos en discos de <strong>fieltro</strong>.</p><h2 id=\"materiais\">Materiales</h2><div class=\"highlight\"><ul><li><strong>1 cubeta rígida</strong> con tapa (10–20 L)</li><li><strong>1 bomba de acuario sumergible</strong></li><li><strong>Kit de aspersores</strong> para riego</li><li><strong>Tapete de fieltro</strong></li><li><strong>Agua</strong> limpia</li><li><strong>Perforador, tijeras o cúter</strong></li><li><strong>Gel de enraizamiento</strong> (opcional)</li></ul></div><p class=\"field-hint\">Todo puede comprarse en una tienda común: tienda de mascotas, materiales ligeros de construcción o mercado.</p><h2>Montaje — paso a paso</h2><h3>Paso 1 — Preparar la cubeta</h3><ol><li>Lava bien la cubeta y la tapa.</li><li>Coloca la <strong>bomba sumergible</strong> en el fondo.</li><li>Agrega <strong>poca agua</strong>, solo la necesaria para que la bomba y el aspersor funcionen.</li></ol><h3>Paso 2 — Cortar la tapa y los agujeros redondos</h3><ol><li>Marca hasta <strong>12 puntos</strong> en la tapa, separados 15–20 cm.</li><li><strong>Corta agujeros redondos</strong>, uno para cada esqueje.</li><li>Cada agujero debe encajar un disco de fieltro que sostenga el tallo.</li></ol><h3>Paso 3 — Fieltro como soporte</h3><ol><li>Corta el <strong>tapete de fieltro</strong> en <strong>12 discos</strong>.</li><li>Haz un corte hasta la mitad de cada disco.</li><li>Encaja el tallo en el fieltro y presiónalo en el agujero de la tapa.</li></ol><h3>Paso 4 — Instalar el kit de aspersores</h3><ol><li>Conecta la salida de la bomba a la <strong>manguera del kit de riego</strong>.</li><li>Apunta los <strong>microaspersores</strong> a la <strong>base de los esquejes</strong>.</li><li>Fija las mangueras a la tapa o los laterales.</li><li>Pasa el cable de la bomba por la tapa o lateral.</li></ol><h3>Paso 5 — Esquejes y operación</h3><ol><li>Inserta los esquejes en los soportes de fieltro, con la base cerca del chorro.</li><li>Cierra la tapa.</li><li>Deja la bomba encendida <strong>24 horas al día</strong> — <strong>sin temporizador</strong>.</li><li>El agua se pulveriza sobre las raíces hasta el trasplante.</li></ol><h2>Cómo saber si está bien</h2><ul><li>Ves u oyes la <strong>aspersión continua</strong> en la zona de raíces.</li><li>La bomba permanece <strong>sumergida</strong> — nunca la enciendas en seco.</li><li>Los esquejes quedan firmes y húmedos en la base.</li><li>El nivel de agua se mantiene bajo; completa si se evapora.</li></ul><h2>¿Cuánto tarda en salir la raíz?</h2><p>En general, <strong>7 a 14 días</strong>. Cuando las raíces tengan <strong>2 a 3 cm</strong>, trasplanta. Mantén la aspersión hasta entonces.</p><h2>Cuidados</h2><ul><li><strong>Agua:</strong> cámbiala cada 5–7 días o si se enturbia u huele mal.</li><li><strong>Temperatura:</strong> 20–26 °C; evita el sol directo.</li><li><strong>Aspersores:</strong> limpia si se obstruyen.</li><li><strong>Fieltro:</strong> reemplázalo si se pudre o huele mal.</li></ul><h2>Problemas comunes</h2><p><strong>La bomba no pulveriza:</strong> nivel bajo, aspersor obstruido o manguera suelta.</p><p><strong>Esqueje marchito:</strong> chorro débil, calor alto o soporte flojo.</p><p><strong>Agua con olor:</strong> cámbiala de inmediato y limpia la cubeta.</p><div class=\"highlight\"><p style=\"margin:0;\"><strong>Lista rápida:</strong> cubeta con tapa · bomba sumergible · kit de microaspersores · fieltro · agua · perforador/tijeras · gel de enraizamiento (opcional).</p></div><p class=\"manual-variant-back\"><a href=\"/equipamentos/clonadora-6-estacas.html\">← Ver también: clonadora de 6 esquejes (recipiente de helado)</a></p></div>"}},"equipamentos/manual-clonadora.html":{"en":{"title":"Cloning Machines | Inspetor BudGanja","bodyHtml":""},"es":{"title":"Clonadoras | Inspetor BudGanja","bodyHtml":""}},"equipamentos/manual-hidrocloradora.html":{"en":{"title":"12-cutting cloning machine | Inspetor BudGanja","bodyHtml":""},"es":{"title":"Clonadora de 12 esquejes | Inspetor BudGanja","bodyHtml":""}}};
